"""
src/twin/alert_system.py
Tiered Clinical Alert System with 4-Tier Risk Classification and Fatigue Suppression.
"""

from dataclasses import dataclass
from datetime import datetime, timedelta
from typing import Any, Dict, List, Literal, Optional, Tuple

RiskTier = Literal["GREEN", "YELLOW", "ORANGE", "RED"]
EventType = Literal["hyperglycaemia", "hypoglycaemia", "none"]


@dataclass
class Alert:
    """Represents an actionable clinical alert generated by the Digital Twin."""
    patient_id: str
    timestamp: datetime
    tier: RiskTier
    risk_score: float
    event_type: EventType
    predicted_event_in_minutes: Optional[int]
    message: str
    shap_features: Optional[List[dict]] = None


class AlertSystem:
    """
    Translates continuous risk scores into calibrated clinical alerts.
    Enforces intelligent alert suppression to eliminate alarm fatigue in hospital wards.
    """

    TIER_THRESHOLDS: Dict[RiskTier, Tuple[float, float]] = {
        "GREEN": (0.0, 0.30),
        "YELLOW": (0.30, 0.60),
        "ORANGE": (0.60, 0.80),
        "RED": (0.80, 1.01),
    }

    ALERT_MESSAGES: Dict[RiskTier, str] = {
        "GREEN": "Patient within target glycemic range. No clinical intervention required.",
        "YELLOW": "Mild glycemic instability detected. Continuous monitoring recommended.",
        "ORANGE": "High risk of adverse glycemic event within 90-120 minutes. Prepare preventative intervention.",
        "RED": "Critical: Adverse glycemic excursion predicted within 60 minutes. Immediate clinical action required.",
    }

    def __init__(self, fatigue_suppression_minutes: int = 30):
        self.fatigue_suppression_minutes = fatigue_suppression_minutes
        self.alert_history: Dict[str, List[Alert]] = {}

    def classify_risk(self, risk_score: float) -> RiskTier:
        """Map continuous risk score [0, 1] into a discrete clinical tier."""
        score = float(risk_score)
        if score >= 0.80:
            return "RED"
        elif score >= 0.60:
            return "ORANGE"
        elif score >= 0.30:
            return "YELLOW"
        else:
            return "GREEN"

    def _predict_event_type(self, current_glucose: float, glucose_roc: float, iob: float) -> EventType:
        """Differentiate between impending hypoglycemia vs hyperglycemia."""
        if current_glucose < 100.0 and (glucose_roc < -1.0 or iob > 2.0):
            return "hypoglycaemia"
        elif current_glucose > 180.0 or glucose_roc > 1.2:
            return "hyperglycaemia"
        elif current_glucose <= 110.0 and glucose_roc < -0.5:
            return "hypoglycaemia"
        else:
            return "hyperglycaemia"

    def _estimate_event_eta(self, risk_score: float, current_glucose: float, glucose_roc: float) -> int:
        """
        Estimate clinical time-to-event (ETA) in minutes.
        Guaranteed to fall within [10, 120] minutes.
        """
        base_eta = int((1.0 - min(1.0, max(0.0, risk_score))) * 120.0)
        if abs(glucose_roc) > 2.0:
            base_eta = int(base_eta * 0.65)
        return max(10, min(120, base_eta))

    def _build_clinical_message(
        self,
        tier: RiskTier,
        event_type: EventType,
        eta: int,
        current_glucose: float,
        iob: float,
        shap_features: Optional[List[dict]] = None,
    ) -> str:
        """Synthesize contextualized doctor alert message."""
        base = self.ALERT_MESSAGES[tier]
        context = f" [Current Glucose: {current_glucose:.1f} mg/dL | ETA: ~{eta} min | Impending: {event_type.upper()}]"
        if iob > 0.5:
            context += f" [Active IOB: {iob:.1f} U]"
        if event_type == "hypoglycaemia":
            action = " Action: [Physician judgment required] Administer 15g fast-acting carbohydrates / withhold prandial bolus."
        elif event_type == "hyperglycaemia":
            action = " Action: [Physician judgment required] Review basal infusion or calculate corrective insulin titration."
        else:
            action = ""
        return base + context + action

    def generate_alert(
        self,
        patient_id: str,
        timestamp: datetime,
        risk_score: float,
        current_glucose: float,
        glucose_roc: float,
        iob: float = 0.0,
        shap_features: Optional[List[dict]] = None,
    ) -> Optional[Alert]:
        """Generate an Alert object."""
        tier = self.classify_risk(risk_score)
        event_type = self._predict_event_type(current_glucose, glucose_roc, iob)
        eta = self._estimate_event_eta(risk_score, current_glucose, glucose_roc)
        message = self._build_clinical_message(tier, event_type, eta, current_glucose, iob, shap_features)

        alert = Alert(
            patient_id=patient_id,
            timestamp=timestamp,
            tier=tier,
            risk_score=risk_score,
            event_type=event_type,
            predicted_event_in_minutes=eta,
            message=message,
            shap_features=shap_features if tier == "RED" else None,
        )
        return alert

    def load_history_from_records(self, alert_records: List[Dict[str, Any]]) -> None:
        """
        Populate alert history from persistent store (e.g., SQLite alert_logs).
        Ensures fatigue suppression windows remain effective across server restarts.
        """
        for record in alert_records:
            pid = record.get("patient_id")
            if not pid:
                continue
            ts = record.get("timestamp")
            if isinstance(ts, str):
                try:
                    ts_dt = datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    continue
            else:
                ts_dt = ts

            alert = Alert(
                patient_id=pid,
                timestamp=ts_dt,
                tier=record.get("tier", "GREEN"),
                risk_score=float(record.get("risk_score", 0.0)),
                event_type=record.get("event_type", "none"),
                predicted_event_in_minutes=record.get("predicted_event_in_minutes"),
                message=record.get("message", ""),
                shap_features=record.get("shap_features"),
            )
            if pid not in self.alert_history:
                self.alert_history[pid] = []
            self.alert_history[pid].append(alert)

    def process_alert(
        self,
        patient_id: str,
        timestamp: datetime,
        risk_score: float,
        glucose: float,
        roc: float,
        iob: float = 0.0,
        shap_features: Optional[List[dict]] = None,
    ) -> Optional[Alert]:
        """
        Process alert through suppression filter to avoid alarm fatigue.
        Suppresses identical-tier alerts within fatigue_suppression_minutes window.
        """
        tier = self.classify_risk(risk_score)
        if tier in ("GREEN", "YELLOW"):
            return None

        # Check fatigue suppression
        history = self.alert_history.get(patient_id, [])
        cutoff = timestamp - timedelta(minutes=self.fatigue_suppression_minutes)

        for prior_alert in reversed(history):
            if prior_alert.timestamp >= cutoff:
                if prior_alert.tier == tier:
                    # Suppress duplicate alert of same tier within cooldown
                    return None
            else:
                break

        # Fire alert and record in history
        alert = self.generate_alert(patient_id, timestamp, risk_score, glucose, roc, iob, shap_features)
        if patient_id not in self.alert_history:
            self.alert_history[patient_id] = []
        self.alert_history[patient_id].append(alert)
        return alert

